createrfsdeployment:
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{=toJSON(inputs.parameters.sessionName+'-rfs')}}
  ownerReferences:
    - apiVersion: migrations.opensearch.org/v1alpha1
      kind: SnapshotMigration
      name: {{=toJSON(inputs.parameters.crdName)}}
      uid: {{=toJSON(inputs.parameters.crdUid)}}
      controller: false
      blockOwnerDeletion: true
  labels:
    migrations.opensearch.org/component: rfs-worker
    workflows.argoproj.io/workflow: {{=toJSON(workflow.name)}}
    migrations.opensearch.org/source: {{=toJSON(inputs.parameters.sourceK8sLabel)}}
    migrations.opensearch.org/target: {{=toJSON(inputs.parameters.targetK8sLabel)}}
    migrations.opensearch.org/snapshot: {{=toJSON(inputs.parameters.snapshotK8sLabel)}}
    migrations.opensearch.org/from-snapshot-migration: {{=toJSON(inputs.parameters.fromSnapshotMigrationK8sLabel)}}
    migrations.opensearch.org/task: {{=toJSON(inputs.parameters.taskK8sLabel)}}
    migrations.opensearch.org/migration-resource-uid: {{=toJSON(inputs.parameters.crdUid)}}
spec:
  replicas: {{=fromJSON(inputs.parameters.podReplicas)}}
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxUnavailable: 5%
      maxSurge: 10%
  selector:
    matchLabels:
      migrations.opensearch.org/component: rfs-worker
      migrations.opensearch.org/migration-resource-uid: {{=toJSON(inputs.parameters.crdUid)}}
  template:
    metadata:
      labels:
        migrations.opensearch.org/component: rfs-worker
        workflows.argoproj.io/workflow: {{=toJSON(workflow.name)}}
        migrations.opensearch.org/source: {{=toJSON(inputs.parameters.sourceK8sLabel)}}
        migrations.opensearch.org/target: {{=toJSON(inputs.parameters.targetK8sLabel)}}
        migrations.opensearch.org/snapshot: {{=toJSON(inputs.parameters.snapshotK8sLabel)}}
        migrations.opensearch.org/from-snapshot-migration: {{=toJSON(inputs.parameters.fromSnapshotMigrationK8sLabel)}}
        migrations.opensearch.org/task: {{=toJSON(inputs.parameters.taskK8sLabel)}}
        migrations.opensearch.org/migration-resource-uid: {{=toJSON(inputs.parameters.crdUid)}}
        azure.workload.identity/use: {{=toJSON(((inputs.parameters.cloudProvider == 'azure') ? ('true') : ('false')))}}
    spec:
      serviceAccountName: argo-workflow-executor
      nodeSelector: {{=((0 == len(inputs.parameters.workloadNodePoolName)) ? (sprig.dict()) : (sprig.dict("migrations.opensearch.org/workload-pool", inputs.parameters.workloadNodePoolName)))}}
      tolerations: {{=((0 == len(inputs.parameters.workloadNodePoolName)) ? ([]) : ([sprig.dict("key", 'migrations.opensearch.org/workload-pool', "operator", 'Equal', "value", inputs.parameters.workloadNodePoolName, "effect", 'NoSchedule')]))}}
      topologySpreadConstraints: {{=((inputs.parameters.workloadZoneSpread == 'none') ? ([]) : ([sprig.merge(sprig.dict("maxSkew", 1, "topologyKey", 'topology.kubernetes.io/zone', "whenUnsatisfiable", ((inputs.parameters.workloadZoneSpread == 'required') ? ('DoNotSchedule') : ('ScheduleAnyway')), "nodeTaintsPolicy", 'Honor', "labelSelector", sprig.dict(), "matchLabelKeys", ["migrations.opensearch.org/component","migrations.opensearch.org/migration-resource-uid"]), ((inputs.parameters.workloadZoneSpread == 'required') ? (fromJSON(inputs.parameters.workloadZoneSpreadExtras)) : (sprig.dict())))]))}}
      containers:
        - name: bulk-loader
          image: {{=toJSON(inputs.parameters.imageReindexFromSnapshotLocation)}}
          imagePullPolicy: {{=toJSON(inputs.parameters.imageReindexFromSnapshotPullPolicy)}}
          command:
            - /rfs-app/runJavaWithClasspathWithRepeat.sh
          args:
            - org.opensearch.migrations.RfsMigrateDocuments
            - ---INLINE-JSON
            - "{{=toBase64(inputs.parameters.rfsJsonConfig)}}"
          resources: {{=fromJSON(inputs.parameters.resources)}}
          env:
            - name: TARGET_USERNAME
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.targetBasicCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.targetBasicCredsSecretNameOrEmpty)))}}
                  key: username
                  optional: true
            - name: TARGET_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.targetBasicCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.targetBasicCredsSecretNameOrEmpty)))}}
                  key: password
                  optional: true
            - name: COORDINATOR_USERNAME
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.coordinatorBasicCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.coordinatorBasicCredsSecretNameOrEmpty)))}}
                  key: username
                  optional: true
            - name: COORDINATOR_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.coordinatorBasicCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.coordinatorBasicCredsSecretNameOrEmpty)))}}
                  key: password
                  optional: true
            - name: AZURE_STORAGE_ACCOUNT_KEY
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.azureCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.azureCredsSecretNameOrEmpty)))}}
                  key: accountKey
                  optional: true
            - name: AZURE_STORAGE_SAS_TOKEN
              valueFrom:
                secretKeyRef:
                  name: {{=toJSON(((0 == len(inputs.parameters.azureCredsSecretNameOrEmpty)) ? ('empty') : (inputs.parameters.azureCredsSecretNameOrEmpty)))}}
                  key: sasToken
                  optional: true
            - name: MIGRATIONS_ROOT_LOG_LEVEL
              value: {{=toJSON(inputs.parameters.rootLogLevel)}}
            - name: BULK_REQUEST_TRACE_LOG_LEVEL
              value: {{=toJSON(inputs.parameters.bulkRequestTraceLogLevel)}}
            - name: FAILED_REQUESTS_LOGGER_LEVEL
              value: {{=toJSON(inputs.parameters.failedRequestsLogLevel)}}
            - name: CONSOLE_LOG_FORMAT
              value: json
            - name: JDK_JAVA_OPTIONS
              value: {{=toJSON(inputs.parameters.jvmArgs + ' ' + ((!(0 == len(inputs.parameters.loggingConfigurationOverrideConfigMap))) ? ('-Dlog4j2.configurationFile=/config/logConfiguration/configuration') : ('')))}}
            - name: AWS_SHARED_CREDENTIALS_FILE
              value: {{=toJSON(((fromJSON(inputs.parameters.useLocalStack)) ? ('/config/credentials/configuration') : ('')))}}
          volumeMounts: {{=sprig.concat([sprig.dict("name", 'log4j-configuration', "mountPath", '/config/logConfiguration', "readOnly", true), sprig.dict("name", 'localstack-test-creds', "mountPath", '/config/credentials', "readOnly", true)], fromJSON(inputs.parameters.fileSourceVolumeMounts))}}
      volumes: {{=sprig.concat([sprig.dict("name", 'log4j-configuration', "configMap", sprig.dict("name", sprig.default('default-log4j-config', inputs.parameters.loggingConfigurationOverrideConfigMap), "optional", !(!(0 == len(inputs.parameters.loggingConfigurationOverrideConfigMap))))), sprig.dict("name", 'localstack-test-creds', "configMap", sprig.dict("name", 'localstack-test-creds', "optional", !(fromJSON(inputs.parameters.useLocalStack))))], fromJSON(inputs.parameters.fileSourceVolumes))}}

